1	// Minimal ESC/POS command builder for thermal kitchen-ticket printing.
2	// Text is sent as latin1 bytes (matches the default CP437-ish codepage on
3	// most cheap 58/80mm thermal printers for the plain-ASCII characters we use).
4	
5	const ESC = 0x1b;
6	const GS = 0x1d;
7	
8	export type KitchenTicketItem = {
9	  name: string;
10	  qty: number;
11	  note?: string | null;
12	};
13	
14	export type KitchenTicketInput = {
15	  station: string;
16	  source: string;
17	  label: string;
18	  items: KitchenTicketItem[];
19	};
20	
21	function formatQty(qty: number): string {
22	  return Number.isInteger(qty) ? String(qty) : qty.toFixed(2);
23	}
24	
25	export function buildKitchenTicket(input: KitchenTicketInput): Buffer {
26	  const chunks: Buffer[] = [];
27	  const push = (bytes: number[]) => chunks.push(Buffer.from(bytes));
28	  const text = (s: string) => chunks.push(Buffer.from(`${s}\n`, "latin1"));
29	
30	  push([ESC, 0x40]); // initialize
31	
32	  push([ESC, 0x61, 0x01]); // center align
33	  push([GS, 0x21, 0x11]); // double width + height
34	  text(input.station.toUpperCase());
35	  push([GS, 0x21, 0x00]); // back to normal size
36	
37	  push([ESC, 0x61, 0x00]); // left align
38	  text(`${input.source} - ${input.label}`);
39	  text(new Date().toLocaleString("id-ID"));
40	  text("--------------------------------");
41	
42	  for (const item of input.items) {
43	    push([ESC, 0x45, 0x01]); // bold on
44	    text(`${formatQty(item.qty)}x ${item.name}`);
45	    push([ESC, 0x45, 0x00]); // bold off
46	    if (item.note) {
47	      text(`   Catatan: ${item.note}`);
48	    }
49	  }
50	
51	  text("");
52	  text("");
53	  push([GS, 0x56, 0x42, 0x00]); // partial cut with feed
54	
55	  return Buffer.concat(chunks);
56	}
57	
58	// 32 columns matches Font A on the 58mm thermal printers this app targets
59	// (RPP02N and similar) — used to right-align prices/totals in plain text
60	// since ESC/POS has no flex layout.
61	const RECEIPT_WIDTH = 32;
62	
63	function padLine(left: string, right: string, width = RECEIPT_WIDTH): string {
64	  const space = Math.max(width - left.length - right.length, 1);
65	  return left + " ".repeat(space) + right;
66	}
67	
68	function truncate(s: string, width = RECEIPT_WIDTH): string {
69	  return s.length > width ? s.slice(0, width) : s;
70	}
